settings.custom_liquid:
{% comment %}
  Swaptop Footer
  Drop into: sections/swaptop-footer.liquid
  { "type": "swaptop-footer" }
{% endcomment %}

<style>
.contact-form.section.section--padding.color-scheme-1 {
    background: #f4f9fd;
}
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');

  .spt-bottom {
    font-family: 'Inter', sans-serif;
    background: #000;
    padding: 20px 24px;
    border-top: 1px solid #1a1a1a;
  }

  .spt-inner {
    max-width: 1100px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
  }

  .spt-copy {
    font-size: 13px;
    color: rgba(255,255,255,0.35);
    font-weight: 400;
    white-space: nowrap;
  }

  .spt-links {
    display: flex;
    align-items: center;
    gap: 4px;
    flex-wrap: wrap;
  }

  .spt-link {
    font-size: 13px;
    font-weight: 500;
    color: rgba(255,255,255,0.5);
    text-decoration: none;
    padding: 4px 10px;
    border-radius: 6px;
    transition: color 0.2s, background 0.2s;
    white-space: nowrap;
  }

  .spt-link:hover {
    color: #fff;
    background: rgba(255,255,255,0.07);
  }

  .spt-sep {
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: rgba(255,255,255,0.2);
    flex-shrink: 0;
  }

  @media (max-width: 600px) {
    .spt-inner {
      flex-direction: column;
      align-items: center;
      gap: 12px;
      text-align: center;
    }

    .spt-links {
      justify-content: center;
    }
  }
</style>

<div class="spt-bottom">
  <div class="spt-inner">

    <span class="spt-copy">&copy; {{ 'now' | date: '%Y' }} PopDarts. All rights reserved.</span>

    <nav class="spt-links">
      <a class="spt-link" href="/policies/privacy-policy">Privacy Policy</a>
      <span class="spt-sep"></span>
      <a class="spt-link" href="/policies/terms-of-service">Terms of Service</a>
      <span class="spt-sep"></span>
      <a class="spt-link" href="/policies/shipping-policy">Shipping Policy</a>
      <span class="spt-sep"></span>
      <a class="spt-link" href="/policies/refund-policy">Refund Policy</a>
    </nav>

  </div>
</div>
